#include <iostream>
#include <iomanip>

int main() {
    // Print the first 20 prime numbers, 5 per line
    const int NUMBER_OF_PRIMES = 20;
    const int PER_LINE = 5;
    int count = 0;
    int candidate = 2;

    std::cout << "The first " << NUMBER_OF_PRIMES << " prime numbers are:\n";

    while (count < NUMBER_OF_PRIMES) {
        bool is_prime = true;
        for (int divisor = 2; divisor <= candidate / 2; ++divisor) {
            if (candidate % divisor == 0) {
                is_prime = false;
                break; // Exit testing loop early
            }
        }

        if (is_prime) {
            ++count;
            std::cout << std::setw(5) << candidate;
            if (count % PER_LINE == 0) {
                std::cout << '\n';
            }
        }
        ++candidate;
    }

    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    // Demonstrate sentinel-controlled input and continue skipping invalid items
    int value;
    int positive_count = 0;
    int negative_count = 0;
    long long total = 0;

    while (std::cin >> value) {
        if (value == 0) {
            break; // Sentinel 0 encountered: stop reading
        }

        if (value > 0) {
            ++positive_count;
        } else {
            ++negative_count;
        }
        total += value;
    }

    int total_numbers = positive_count + negative_count;
    if (total_numbers == 0) {
        std::cout << "No numbers are entered except 0\n";
    } else {
        std::cout << "The number of positives is " << positive_count << '\n';
        std::cout << "The number of negatives is " << negative_count << '\n';
        std::cout << "The total is " << total << '\n';
        double average = static_cast<double>(total) / total_numbers;
        std::cout << std::fixed << std::setprecision(2);
        std::cout << "The average is " << average << '\n';
    }

    return 0;
}
